import numpy as np
from landlab import NodeStatus
from landlab import VoronoiDelaunayGrid
from landlab.components.flow_director import flow_direction_DN
from landlab.components.flow_director.flow_director_to_one import _FlowDirectorToOne

class FlowDirectorSteepest(_FlowDirectorToOne):
    _name = 'FlowDirectorSteepest'
    _unit_agnostic = True
    _info = {'flow__link_direction': {'dtype': np.int8, 'intent': 'out', 'optional': False, 'units': '-', 'mapping': 'link', 'doc': 'Direction of flow on link. A value of -1 indicates that water flow goes from head node to tail node, while a value of 1 indicates that water flow goes from tail node to head node.'}, 'flow__link_to_receiver_node': {'dtype': int, 'intent': 'out', 'optional': False, 'units': '-', 'mapping': 'node', 'doc': 'ID of link downstream of each node, which carries the discharge'}, 'flow__receiver_node': {'dtype': int, 'intent': 'out', 'optional': False, 'units': '-', 'mapping': 'node', 'doc': 'Node array of receivers (node that receives flow from current node)'}, 'flow__sink_flag': {'dtype': bool, 'intent': 'out', 'optional': False, 'units': '-', 'mapping': 'node', 'doc': 'Boolean array, True at local lows'}, 'topographic__elevation': {'dtype': float, 'intent': 'in', 'optional': True, 'units': 'm', 'mapping': 'node', 'doc': 'Land surface topographic elevation'}, 'topographic__steepest_slope': {'dtype': float, 'intent': 'out', 'optional': False, 'units': '-', 'mapping': 'node', 'doc': 'The steepest *downhill* slope'}}

    def __init__(self, grid, surface='topographic__elevation'):
        self._method = 'D4'
        super().__init__(grid, surface)
        self._is_Voroni = isinstance(self._grid, VoronoiDelaunayGrid)
        self._flow_link_direction = grid.at_link['flow__link_direction']
        self.updated_boundary_conditions()

    def updated_boundary_conditions(self):
        self._active_links = self._grid.active_links
        self._activelink_tail = self._grid.node_at_link_tail[self._grid.active_links]
        self._activelink_head = self._grid.node_at_link_head[self._grid.active_links]

    def run_one_step(self):
        self.direct_flow()

    def direct_flow(self):
        self._check_updated_bc()
        self._changed_surface()
        all_grads = -self._grid.calc_grad_at_link(self._surface_values)
        link_slope = all_grads[self._grid.active_links]
        baselevel_nodes, = np.where(np.logical_or(self._grid.status_at_node == NodeStatus.FIXED_VALUE, self._grid.status_at_node == NodeStatus.FIXED_GRADIENT))
        receiver, steepest_slope, sink, recvr_link = flow_direction_DN.flow_directions(self._surface_values, self._active_links, self._activelink_tail, self._activelink_head, link_slope, grid=self._grid, baselevel_nodes=baselevel_nodes)
        self._grid['node']['flow__receiver_node'][:] = receiver
        self._grid['node']['topographic__steepest_slope'][:] = steepest_slope
        self._grid['node']['flow__link_to_receiver_node'][:] = recvr_link
        self._grid['node']['flow__sink_flag'][:] = np.zeros_like(receiver, dtype=bool)
        self._grid['node']['flow__sink_flag'][sink] = True
        self._determine_link_directions()
        return receiver

    def _determine_link_directions(self):
        self._flow_link_direction[:] = 0
        is_active_flow_link = self._links_to_receiver != self._grid.BAD_INDEX
        active_flow_links = self._links_to_receiver[is_active_flow_link]
        upstream_node_of_active_flow_link = np.where(is_active_flow_link)[0]
        head_node_at_active_flow_link = self._grid.node_at_link_head[active_flow_links]
        self._flow_link_direction[active_flow_links[head_node_at_active_flow_link == upstream_node_of_active_flow_link]] = -1
        self._flow_link_direction[active_flow_links[head_node_at_active_flow_link != upstream_node_of_active_flow_link]] = 1

    def flow_link_direction_at_node(self):
        flow_link_direction_at_node = self._flow_link_direction[self._grid.links_at_node]
        flow_to_bad = self._grid.links_at_node == self._grid.BAD_INDEX
        flow_link_direction_at_node[flow_to_bad] = 0
        return flow_link_direction_at_node

    def flow_link_incoming_at_node(self):
        incoming_at_node = self.flow_link_direction_at_node() * self._grid.link_dirs_at_node
        return incoming_at_node

    @property
    def flow_link_direction(self):
        return self._flow_link_direction

    def upstream_node_at_link(self):
        out = -1 * self._grid.ones(at='link', dtype=int)
        out[self._flow_link_direction == 1] = self._grid.node_at_link_tail[self._flow_link_direction == 1]
        out[self._flow_link_direction == -1] = self._grid.node_at_link_head[self._flow_link_direction == -1]
        return out

    def downstream_node_at_link(self):
        out = -1 * self._grid.ones(at='link', dtype=int)
        out[self._flow_link_direction == 1] = self._grid.node_at_link_head[self._flow_link_direction == 1]
        out[self._flow_link_direction == -1] = self._grid.node_at_link_tail[self._flow_link_direction == -1]
        return out
